            let mem = escMem[f.mla];
            const uv = Math.max(ultE[f.mla] || 0, ultPC[(e.prodId || '') + '__' + (e.cuenta || f.cuenta)] || 0);
            // P4 de la segunda vuelta (25/09/2026): la memoria de la escalera se BORRA cuando vendió
